arguments.new_string:
_pickPart(e) {
  this.raycaster.setFromCamera(this._ndc(e), this.camera);
  const hits = this.raycaster.intersectObjects([...this.world.meshes.values()]);
  for (const h of hits) {
    if (!h.object.isMesh) continue;
    // parts are groups now — walk up to the node carrying the part data
    let o = h.object;
    while (o && !o.userData.part) o = o.parent;
    if (o && o.userData.part) return o.userData.part;
  }
  return null;
}
